function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - 100, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // conventional farming
  ctx.fillStyle = 'gray';
  ctx.beginPath();
  ctx.rect(100, H / 2, 100, 100);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Chemicals', 150, H / 2 + 50);

  // organic farming
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.rect(W - 200, H / 2, 100, 100);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Natural', W - 150, H / 2 + 50);

  // comparison
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W / 2 - 50, H / 2 + 120);
  ctx.lineTo(W / 2 + 50, H / 2 + 120);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Which is better?', W / 2, H / 2 + 150);

  // stick figures
  ctx.lineWidth = 4;
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(150, H / 2 - 20, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(150, H / 2);
  ctx.lineTo(150, H / 2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(150, H / 2 + 20);
  ctx.lineTo(120, H / 2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(150, H / 2 + 20);
  ctx.lineTo(180, H / 2 + 40);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W - 150, H / 2 - 20 + Math.sin(t) * 20, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W - 150, H / 2 + Math.sin(t) * 20);
  ctx.lineTo(W - 150, H / 2 + 50 + Math.sin(t) * 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - 150, H / 2 + 20 + Math.sin(t) * 20);
  ctx.lineTo(W - 170, H / 2 + 40 + Math.sin(t) * 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - 150, H / 2 + 20 + Math.sin(t) * 20);
  ctx.lineTo(W - 130, H / 2 + 40 + Math.sin(t) * 20);
  ctx.stroke();

  ctx.restore();
}
